#include <bits/stdc++.h>
using namespace std;

int main() {
    string trump, card1, card2;
    cin >> trump >> card1 >> card2;

    auto rank = [](char c) {
        if (isdigit(static_cast<unsigned char>(c))) return c - '0';
        if (c == 'T') return 10;
        if (c == 'J') return 11;
        if (c == 'Q') return 12;
        if (c == 'K') return 13;
        return 14;
    };

    int p1 = rank(card1[0]);
    int p2 = rank(card2[0]);
    char suit1 = card1[1];
    char suit2 = card2[1];
    char trumpSuit = trump[0];

    if ((suit1 == trumpSuit && suit2 != trumpSuit) ||
        (suit1 == suit2 && p1 > p2)) {
        cout << "YES\n";
    } else {
        cout << "NO\n";
    }

    return 0;
}

